<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{api,type ApiResponse}from'@whaashop/shared';interface Banner{id?:number;title:string;subtitle:string;imageUrl:string;targetUrl:string;buttonText:string;sortOrder:number;enabled:boolean}const rows=ref<Banner[]>([]),dialog=ref(false),uploading=ref(false),form=reactive<Banner>({title:'',subtitle:'',imageUrl:'',targetUrl:'',buttonText:'立即选购',sortOrder:0,enabled:true});async function load(){rows.value=(await api.get<ApiResponse<Banner[]>>('/admin/home-banners')).data.data}function edit(v?:Banner){Object.assign(form,v??{id:undefined,title:'',subtitle:'',imageUrl:'',targetUrl:'',buttonText:'立即选购',sortOrder:0,enabled:true});dialog.value=true}async function upload(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;uploading.value=true;try{const data=new FormData();data.append('file',file);form.imageUrl=(await api.post<ApiResponse<{url:string}>>('/admin/files/banner-images',data)).data.data.url;ElMessage.success('图片上传成功')}finally{uploading.value=false}}async function save(){if(form.id)await api.put(`/admin/home-banners/${form.id}`,form);else await api.post('/admin/home-banners',form);dialog.value=false;ElMessage.success('轮播配置已保存');load()}async function remove(id:number){await ElMessageBox.confirm('确认删除这张轮播图？','提示');await api.delete(`/admin/home-banners/${id}`);load()}onMounted(load)</script>
<template><div class="panel"><div class="toolbar"><div><h2>首页商品轮播</h2><p style="color:#7290a8">配置商城首页大横幅的商品、图片、文案和跳转地址。</p></div><el-button type="primary" @click="edit()">新增轮播</el-button></div><el-table :data="rows"><el-table-column label="预览" width="180"><template #default="s"><el-image :src="s.row.imageUrl" style="width:150px;height:76px;border-radius:9px" fit="cover"/></template></el-table-column><el-table-column prop="title" label="标题"/><el-table-column prop="subtitle" label="副标题" min-width="200" show-overflow-tooltip/><el-table-column prop="targetUrl" label="跳转地址"/><el-table-column prop="sortOrder" label="排序" width="80"/><el-table-column label="状态" width="90"><template #default="s"><el-tag :type="s.row.enabled?'success':'info'">{{s.row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="140"><template #default="s"><el-button link type="primary" @click="edit(s.row)">编辑</el-button><el-button link type="danger" @click="remove(s.row.id)">删除</el-button></template></el-table-column></el-table><el-empty v-if="!rows.length" description="暂无轮播配置"/></div><el-dialog v-model="dialog" :title="form.id?'编辑首页轮播':'新增首页轮播'" width="680"><el-form label-width="90"><el-form-item label="标题"><el-input v-model="form.title" maxlength="120"/></el-form-item><el-form-item label="副标题"><el-input v-model="form.subtitle" type="textarea" maxlength="300"/></el-form-item><el-form-item label="轮播图片"><div style="width:100%"><el-input v-model="form.imageUrl" placeholder="图片地址或上传图片"/><label style="display:inline-block;margin-top:8px"><el-button :loading="uploading" @click.prevent>上传图片</el-button><input type="file" hidden accept="image/jpeg,image/png,image/webp" @change="upload"></label><el-image v-if="form.imageUrl" :src="form.imageUrl" style="display:block;width:100%;height:180px;margin-top:10px;border-radius:10px" fit="cover"/></div></el-form-item><el-form-item label="跳转地址"><el-input v-model="form.targetUrl" placeholder="例如 /products/10001"/></el-form-item><el-form-item label="按钮文字"><el-input v-model="form.buttonText"/></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sortOrder"/></el-form-item><el-form-item label="启用"><el-switch v-model="form.enabled"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存轮播</el-button></template></el-dialog></template>
